import 'dart:io';import 'package:cloud_firestore/cloud_firestore.dart';import 'package:flutter/material.dart';import 'package:geolocator/geolocator.dart';import 'package:image_picker/image_picker.dart';import 'product_service.dart';class ProductUploadScreen extends StatefulWidget{const ProductUploadScreen({super.key});@override State<ProductUploadScreen> createState()=>_S();}class _S extends State<ProductUploadScreen>{final title=TextEditingController(),description=TextEditingController(),price=TextEditingController(),location=TextEditingController();final picker=ImagePicker();final images=<File>[];String category='Lainnya';bool loading=false;Future<void> pick(ImageSource source)async{if(source==ImageSource.camera){final x=await picker.pickImage(source:source,imageQuality:85);if(x!=null)setState(()=>images.add(File(x.path)));}else{final xs=await picker.pickMultiImage(imageQuality:85);setState(()=>images.addAll(xs.map((e)=>File(e.path))));}}Future<void> save()async{if(title.text.trim().isEmpty||price.text.isEmpty||images.isEmpty)return;setState(()=>loading=true);try{double lat=0,lng=0;try{final p=await Geolocator.getCurrentPosition();lat=p.latitude;lng=p.longitude;}catch(_){}await ProductService().createProduct(title:title.text,description:description.text,price:int.tryParse(price.text)??0,images:images,latitude:lat,longitude:lng,category:category,locationName:location.text);if(mounted)Navigator.pop(context);}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Pasang Iklan')),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('Jual barang ke pembeli di sekitar Anda.',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),const SizedBox(height:12),Wrap(spacing:8,runSpacing:8,children:[...images.map((f)=>ClipRRect(borderRadius:BorderRadius.circular(14),child:Image.file(f,width:90,height:90,fit:BoxFit.cover))),OutlinedButton.icon(onPressed:()=>pick(ImageSource.gallery),icon:const Icon(Icons.photo_library),label:const Text('Galeri')),OutlinedButton.icon(onPressed:()=>pick(ImageSource.camera),icon:const Icon(Icons.camera_alt),label:const Text('Kamera'))]),TextField(controller:title,decoration:const InputDecoration(labelText:'Judul iklan')),StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('categories').where('active',isEqualTo:true).snapshots(),builder:(c,s){final a=['Lainnya',...((s.data?.docs??[]).map((d)=>d.data()['name'].toString()))].toSet().toList();if(!a.contains(category))category=a.first;return DropdownButtonFormField(value:category,items:a.map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>setState(()=>category=v!));}),TextField(controller:price,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Harga')),TextField(controller:location,decoration:const InputDecoration(labelText:'Kota / lokasi')),TextField(controller:description,maxLines:5,decoration:const InputDecoration(labelText:'Deskripsi')),const SizedBox(height:20),FilledButton.icon(onPressed:loading?null:save,icon:const Icon(Icons.publish),label:Text(loading?'Mengunggah...':'Terbitkan Iklan'))]));}}